INSERT INTO pipelines(workspace_id,name,description,is_default) SELECT id,'Default Sales Pipeline','Default opportunity pipeline',true FROM workspaces w WHERE NOT EXISTS(SELECT 1 FROM pipelines p WHERE p.workspace_id=w.id);
INSERT INTO pipeline_stages(pipeline_id,name,position,probability) SELECT p.id,s.name,s.position,s.probability FROM pipelines p CROSS JOIN (VALUES('New',1,10),('Qualified',2,30),('Proposal',3,60),('Negotiation',4,80),('Won',5,100),('Lost',6,0)) s(name,position,probability) WHERE p.is_default AND NOT EXISTS(SELECT 1 FROM pipeline_stages ps WHERE ps.pipeline_id=p.id);